const exchangeListJobs = `-- name: ExchangeListJobs :many
select public_id, format, filename, status, created_count, matched_count, skipped_count,
       jsonb_array_length(row_errors)::int as error_count, created_at
from import_jobs
where user_id = $1
order by created_at desc, id desc
limit 20
`

type ExchangeListJobsRow struct {
	PublicID     uuid.UUID
	Format       string
	Filename     string
	Status       string
	CreatedCount int32
	MatchedCount int32
	SkippedCount int32
	ErrorCount   int32
	CreatedAt    time.Time
}

func (q *Queries) ExchangeListJobs(ctx context.Context, userID int64) ([]ExchangeListJobsRow, error) {
	rows, err := q.db.Query(ctx, exchangeListJobs, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ExchangeListJobsRow{}
	for rows.Next() {
		var i ExchangeListJobsRow
		if err := rows.Scan(
			&i.PublicID,
			&i.Format,
			&i.Filename,
			&i.Status,
			&i.CreatedCount,
			&i.MatchedCount,
			&i.SkippedCount,
			&i.ErrorCount,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

